import json, html
from cases import CASES
M = {int(k): v for k, v in json.load(open('media.json')).items()}

CSS = """<style>.kyt{font-family:system-ui,-apple-system,"Segoe UI",Roboto,sans-serif;color:#18212f;font-size:17px;line-height:1.75;max-width:900px;margin:0 auto}.kyt *{box-sizing:border-box}.kyt p{margin:0 0 14px}.kyt-hero{padding:32px 24px;border-radius:12px;background:#f4f8ff;border:1px solid #d9e7ff;margin:0 0 28px}.kyt-kicker{font-size:.85rem;font-weight:700;color:#0f5b9c;margin:0 0 10px;text-transform:uppercase;letter-spacing:.02em}.kyt-lead{font-size:1.12rem;margin:0 0 14px}.kyt-note{border-radius:10px;padding:14px 18px;background:#fffbea;border:1px solid #f1dc8a;font-size:.95rem;line-height:1.65;margin:14px 0 0}.kyt-legend{display:flex;flex-wrap:wrap;gap:8px 16px;font-size:.9rem;margin:0 0 28px;padding:12px 16px;border:1px solid #dbe4ef;border-radius:10px;background:#fff}.kyt-legend span{display:inline-flex;align-items:center;gap:6px}.kyt-dot{display:inline-block;width:14px;height:14px;border-radius:50%}.kyt-line{display:inline-block;width:26px;height:0;border-top:4px solid}.kyt-nav{display:flex;flex-wrap:wrap;gap:6px;margin:0 0 24px}.kyt-nav a{display:inline-block;padding:4px 11px;border-radius:999px;background:#eef4ff;border:1px solid #cfe0fb;font-size:.86rem;font-weight:600;text-decoration:none;color:#0b4f8a}.kyt-case{border:1px solid #dbe4ef;border-radius:14px;background:#fff;margin:0 0 30px;overflow:hidden;scroll-margin-top:80px}.kyt-case h2{font-size:1.32rem;line-height:1.35;margin:0;padding:18px 20px 6px;font-weight:800}.kyt-num{display:inline-block;background:#0f172a;color:#fff;border-radius:8px;padding:1px 9px;margin-right:8px;font-size:.95rem;vertical-align:2px}.kyt-sit{padding:0 20px;color:#3a4656}.kyt-fig{margin:6px 0 0;background:#f8fafc;border-top:1px solid #eef2f7;border-bottom:1px solid #eef2f7}.kyt-fig img{display:block;width:100%;height:auto;border:0;box-shadow:none;margin:0}.kyt-body{padding:16px 20px 20px}.kyt-h{font-weight:800;font-size:1rem;margin:4px 0 8px}.kyt-hz{list-style:none;padding:0;margin:0 0 16px}.kyt-hz li{display:flex;gap:10px;align-items:flex-start;margin:0 0 6px;font-size:.97rem;line-height:1.6}.kyt-b{flex:0 0 24px;height:24px;border-radius:50%;background:#dc2626;color:#fff;font-weight:900;font-size:.85rem;display:flex;align-items:center;justify-content:center;margin-top:2px}.kyt-q{list-style:none;padding:0;margin:0}.kyt-q li{border:1px solid #e5eaf1;border-radius:10px;padding:10px 12px;margin:0 0 8px;font-size:.97rem;line-height:1.6}.kyt-q .n{font-weight:800;color:#0f5b9c;margin-right:6px}.kyt details{margin:12px 0 0}.kyt summary{cursor:pointer;display:inline-block;padding:8px 14px;border-radius:8px;background:#0b66c3;color:#fff;font-weight:700;font-size:.93rem;list-style:none}.kyt summary::-webkit-details-marker{display:none}.kyt-ans{margin:12px 0 0}.kyt-ans li{display:flex;gap:10px;align-items:flex-start}.kyt-mk{flex:0 0 30px;height:30px;border-radius:8px;display:flex;align-items:center;justify-content:center;font-weight:900;font-size:1.05rem}.kyt-mk.ok{background:#ecfaf0;color:#17663a;border:1px solid #bfe8cb}.kyt-mk.ng{background:#fff1f0;color:#a1281b;border:1px solid #f6c9c4}.kyt-why{display:block;font-size:.9rem;color:#475467;margin-top:2px}.kyt-lesson{margin:14px 0 0;padding:10px 14px;border-radius:10px;background:#ecfaf0;border:1px solid #bfe8cb;font-size:.95rem}.kyt-steps{padding-left:1.4em}.kyt-steps li{margin:0 0 8px}.kyt-src{font-size:.88rem;color:#536170}@media(max-width:720px){.kyt{font-size:16px}.kyt-hero{padding:22px 16px}.kyt-case h2{font-size:1.12rem;padding:14px 14px 4px}.kyt-sit{padding:0 14px}.kyt-body{padding:12px 14px 16px}}</style>"""

e = html.escape
o = [CSS, '<div class="kyt">']
o.append('<section class="kyt-hero"><p class="kyt-kicker">Persiapan ujian SIM 原付 (Gentsuki)</p>'
         '<p class="kyt-lead"><strong>16 kasus prediksi bahaya (危険予測)</strong> dengan ilustrasi, persis jenis soal bergambar no. 47–48 di ujian tulis 原付.</p>'
         '<p>Di ujian ada 2 soal bergambar. Masing-masing punya 3 pernyataan ○/×, bernilai <strong>2 poin</strong>, dan <strong>hanya dihitung benar kalau ketiganya benar</strong>. Dua soal ini = 4 dari 50 poin, sedangkan batas lulus 45. Jadi salah di sini sangat mahal.</p>'
         '<p class="kyt-note">💡 Cara belajar: lihat gambarnya, tebak dulu bahayanya, jawab 3 pernyataan, lalu klik <strong>Lihat jawaban</strong>.</p></section>')
o.append('<h2 style="font-size:1.4rem;font-weight:800;margin:0 0 10px">Kunci menjawab soal bergambar</h2><ol class="kyt-steps">'
         '<li>Berpikir <strong>「~かもしれない」</strong> (mungkin ada yang keluar, mungkin dia belok), bukan 「~だろう」 (pasti dia menunggu).</li>'
         '<li>Pernyataan yang mengandung <strong>"percepat", "pasti menunggu/mengalah", "cukup klakson", "keluar garis tengah"</strong> hampir selalu <strong>×</strong>.</li>'
         '<li>Pernyataan yang mengandung <strong>"kurangi kecepatan", "tunggu", "cek dengan mata", "rem bertahap"</strong> biasanya <strong>○</strong>, tapi tetap baca alasannya: alasan yang salah membuat pernyataan jadi ×.</li>'
         '<li>Selalu cek bahaya dari <strong>4 arah</strong>: depan, kiri, kanan, dan belakang (spion).</li></ol>')
o.append('<div class="kyt-legend"><span><span class="kyt-dot" style="background:#f97316"></span>Motor Anda (原付)</span><span><span class="kyt-line" style="border-color:#16a34a"></span>Jalur Anda</span><span><span class="kyt-line" style="border-color:#dc2626;border-top-style:dashed"></span>Gerakan berbahaya</span><span><span class="kyt-b" style="display:inline-flex;width:20px;height:20px;flex:none">1</span>Titik bahaya</span><span><span class="kyt-dot" style="background:#fde047;border:1px solid #ca8a04"></span>Lampu sein / hazard</span><span><span class="kyt-dot" style="background:#111827;opacity:.35"></span>Area tidak terlihat</span></div>')
o.append('<nav class="kyt-nav">' + ''.join(f'<a href="#kasus-{i}">{i}. {e(c[0])}</a>' for i, c in enumerate(CASES, 1)) + '</nav>')
for i, (title, sit, hz, qs, lesson) in enumerate(CASES, 1):
    m = M[i]
    o.append(f'<section class="kyt-case" id="kasus-{i}"><h2><span class="kyt-num">{i}</span>{e(title)}</h2><p class="kyt-sit">{sit}</p>')
    o.append(f'<figure class="kyt-fig"><img src="{m["url"]}" alt="{e("Ilustrasi kasus " + str(i) + ": " + title)}" width="{m["w"]}" height="{m["h"]}" loading="lazy" decoding="async"></figure><div class="kyt-body">')
    o.append('<p class="kyt-h">Pernyataan: benar (○) atau salah (×)?</p><ol class="kyt-q">' + ''.join(f'<li><span class="n">({k})</span>{t}</li>' for k, (t, ok, why) in enumerate(qs, 1)) + '</ol>')
    o.append('<details><summary>Lihat jawaban & bahaya ▸</summary><div class="kyt-ans">')
    o.append('<p class="kyt-h">Bahaya yang harus diprediksi</p><ul class="kyt-hz">' + ''.join(f'<li><span class="kyt-b">{k}</span><span>{h}</span></li>' for k, h in enumerate(hz, 1)) + '</ul>')
    o.append('<p class="kyt-h">Jawaban</p><ol class="kyt-q">' + ''.join(f'<li><span class="kyt-mk {"ok" if ok else "ng"}">{"○" if ok else "×"}</span><span><span class="n">({k})</span>{t}<span class="kyt-why">{why}</span></span></li>' for k, (t, ok, why) in enumerate(qs, 1)) + '</ol>')
    o.append(f'<p class="kyt-lesson">✅ Pelajaran: {lesson}</p></div></details></div></section>')
o.append('<p class="kyt-src">Kasus disusun berdasarkan pola soal 危険予測 ujian tulis 原付. Ilustrasi dibuat oleh menkyo.me (diagram, tidak sesuai skala). Aturan detail bisa berbeda; cek situs kepolisian prefektur Anda.</p></div>')
open('page.html', 'w').write(''.join(o)); print(len(''.join(o)))
